// Validation rule: Reject payloads missing required telemetry contract fields
const p = msg.payload;

if (!p || typeof p !== 'object') {
    node.error("Payload is not a valid object", msg);
    msg.errorReason = "Payload must be a non-null JSON object";
    return [null, msg]; // Port 2 = invalid
}

const errors = [];
if (!p.deviceId || typeof p.deviceId !== 'string') errors.push("deviceId missing or invalid string");
if (!p.room || typeof p.room !== 'string') errors.push("room missing or invalid string");
if (typeof p.temperature !== 'number' || isNaN(p.temperature)) errors.push("temperature missing or not a number");
if (typeof p.humidity !== 'number' || isNaN(p.humidity)) errors.push("humidity missing or not a number");
if (typeof p.distance !== 'number' || isNaN(p.distance) || p.distance < 0) errors.push("distance missing or negative number");
if (typeof p.motion !== 'boolean') errors.push("motion missing or not boolean");
if (typeof p.sound !== 'boolean') errors.push("sound missing or not boolean");
if (typeof p.touch !== 'boolean') errors.push("touch missing or not boolean");
if (!p.timestamp || isNaN(new Date(p.timestamp).getTime())) errors.push("timestamp missing or invalid date");

if (errors.length > 0) {
    msg.errorReason = errors.join("; ");
    msg.invalidPayload = p;
    node.warn("Invalid telemetry rejected: " + msg.errorReason);
    return [null, msg]; // Port 2 = invalid path
}

// Port 1 = valid telemetry
return [msg, null];

// Normalizes incoming payload and assigns readable status classifications
const p = msg.payload;

// Configurable thresholds from global context or defaults
const globalContext = global.get('functionGlobalContext') || {};
const TEMP_WARN = globalContext.TEMP_WARNING_THRESHOLD || 32.0;
const TEMP_CRIT = globalContext.TEMP_CRITICAL_THRESHOLD || 35.0;
const HUM_WARN = globalContext.HUMIDITY_WARNING_THRESHOLD || 75.0;
const DIST_NEAR = globalContext.DISTANCE_ALERT_THRESHOLD || 15.0;

// 1. Temperature Status
let tempStatus = 'NORMAL';
if (p.temperature >= TEMP_CRIT) tempStatus = 'CRITICAL';
else if (p.temperature >= TEMP_WARN) tempStatus = 'WARNING';

// 2. Humidity Status
let humStatus = (p.humidity >= HUM_WARN) ? 'WARNING' : 'NORMAL';

// 3. Distance Status
let distStatus = (p.distance < DIST_NEAR) ? 'NEAR' : 'NORMAL';

// 4. Motion Status
let motionStatus = p.motion ? 'MOTION_DETECTED' : 'NO_MOTION';

// 5. Sound Status
let soundStatus = p.sound ? 'SOUND_DETECTED' : 'NORMAL';

// 6. Touch Status
let touchStatus = p.touch ? 'SOS_ACTIVE' : 'NORMAL';

// Preserves original telemetry and enhances with normalization metadata
msg.payload = {
    ...p,
    receivedAt: new Date().toISOString(),
    temperatureStatus: tempStatus,
    humidityStatus: humStatus,
    distanceStatus: distStatus,
    motionStatus: motionStatus,
    soundStatus: soundStatus,
    touchStatus: touchStatus
};

return msg;

// Alert Engine with security state verification and duplicate cooldown
const p = msg.payload;

// Read security state (default DISARMED)
const securityMode = flow.get('securityMode') || 'DISARMED';

// Read alert cooldown timestamps map
let cooldowns = flow.get('alertCooldowns') || {};
const now = Date.now();
const COOLDOWN_MS = (global.get('functionGlobalContext') || {}).ALERT_COOLDOWN_MS || 10000;

function canTrigger(type) {
    const lastTime = cooldowns[type] || 0;
    if (now - lastTime >= COOLDOWN_MS) {
        cooldowns[type] = now;
        flow.set('alertCooldowns', cooldowns);
        return true;
    }
    return false;
}

function makeAlert(type, severity, message) {
    return {
        alertId: 'alt-' + now + '-' + Math.floor(Math.random() * 1000),
        deviceId: p.deviceId,
        room: p.room,
        type: type,
        severity: severity,
        message: message,
        timestamp: new Date().toISOString()
    };
}

const generatedAlerts = [];

// Rule 1: PIR Motion during ARMED security state
if (securityMode === 'ARMED' && p.motion === true) {
    if (canTrigger('MOTION_BREACH')) {
        generatedAlerts.push(makeAlert('MOTION_BREACH', 'CRITICAL', 'Security Breach: Motion detected in ' + p.room + ' while system is ARMED!'));
    }
}

// Rule 2: Capacitive Touch / SOS Key
if (p.touch === true) {
    if (canTrigger('SOS_ACTIVATED')) {
        generatedAlerts.push(makeAlert('SOS_ACTIVATED', 'CRITICAL', 'Emergency SOS: Physical touch key activated in ' + p.room + '!'));
    }
}

// Rule 3: Temperature Thresholds
const globalContext = global.get('functionGlobalContext') || {};
const TEMP_CRIT = globalContext.TEMP_CRITICAL_THRESHOLD || 35.0;
const TEMP_WARN = globalContext.TEMP_WARNING_THRESHOLD || 32.0;

if (p.temperature >= TEMP_CRIT) {
    if (canTrigger('HIGH_TEMP_CRITICAL')) {
        generatedAlerts.push(makeAlert('HIGH_TEMPERATURE', 'CRITICAL', 'Critical Heat: ' + p.temperature + '°C exceeds emergency threshold (' + TEMP_CRIT + '°C)'));
    }
} else if (p.temperature >= TEMP_WARN) {
    if (canTrigger('HIGH_TEMP_WARNING')) {
        generatedAlerts.push(makeAlert('HIGH_TEMPERATURE', 'WARNING', 'High Temperature: ' + p.temperature + '°C exceeds warning threshold (' + TEMP_WARN + '°C)'));
    }
}

// Rule 4: Ultrasonic Obstacle Proximity
const DIST_NEAR = globalContext.DISTANCE_ALERT_THRESHOLD || 15.0;
if (p.distance < DIST_NEAR) {
    if (canTrigger('CLOSE_OBJECT')) {
        generatedAlerts.push(makeAlert('CLOSE_OBJECT', 'WARNING', 'Proximity Warning: Object detected at ' + p.distance + ' cm (Threshold: ' + DIST_NEAR + ' cm)'));
    }
}

// Rule 5: Acoustic Sound Spike
if (p.sound === true) {
    if (canTrigger('SOUND_DETECTED')) {
        generatedAlerts.push(makeAlert('SOUND_DETECTED', 'WARNING', 'Acoustic Alert: Sound event detected in ' + p.room + '.'));
    }
}

// If alerts generated, send them out individually
if (generatedAlerts.length > 0) {
    const messages = generatedAlerts.map(a => ({
        payload: a,
        topic: 'smartsense/room1/alerts'
    }));
    return [messages];
}

return null;

const p = msg.payload;
const securityMode = flow.get('securityMode') || 'DISARMED';

const statusObj = {
    deviceId: p.deviceId,
    room: p.room,
    status: 'ONLINE',
    securityMode: securityMode,
    lastSeen: new Date().toISOString()
};

msg.payload = statusObj;
msg.topic = 'smartsense/room1/status';
return msg;

const p = msg.payload;

msg.payload = {
