return msg;

const a = msg.payload;
const globalContext = global.get('functionGlobalContext') || {};
let baseUrl = (globalContext.FIREBASE_DATABASE_URL || 'http://localhost:9000').replace(/\/$/, '');
const secret = globalContext.FIREBASE_DATABASE_SECRET;
const authQuery = secret ? '?auth=' + secret : '';

msg.url = baseUrl + '/alerts/' + encodeURIComponent(a.alertId) + '.json' + authQuery;
msg.method = 'PUT';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
    alertId: a.alertId,
    deviceId: a.deviceId,
    room: a.room,
    type: a.type,
    severity: a.severity,
    message: a.message,
    timestamp: a.timestamp,
    acknowledged: false
};
return msg;

const mode = msg.payload === 'ARMED' ? 'ARMED' : 'DISARMED';
flow.set('securityMode', mode);
node.status({ fill: mode === 'ARMED' ? 'red' : 'green', shape: 'dot', text: 'MODE: ' + mode });
msg.payload = { securityMode: mode, updatedAt: new Date().toISOString() };
return msg;

flow.set('alertCooldowns', {});
msg.payload = { message: 'Alert cooldowns cleared', timestamp: new Date().toISOString() };
return msg;
